import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export function createDecoder() {
  const utf8 = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  let lineBuffer = '';
  let atStart = true;
  let dataValues = [];
  let eventValue;
  let hasEvent = false;
  let terminated = false;
  let finished = false;
  let poisoned = false;

  function fail(message, cause) {
    poisoned = true;
    throw new Error(message, cause === undefined ? undefined : {cause});
  }

  function processLine(line, frames) {
    if (terminated) {
      if (line !== '') fail('nonblank line after termination');
      return;
    }

    if (line === '') {
      if (dataValues.length !== 0) {
        const data = dataValues.join('\n');
        const event = !hasEvent || eventValue === '' ? 'message' : eventValue;
        if (data === '[DONE]') terminated = true;
        else frames.push({event, data});
      }
      dataValues = [];
      eventValue = undefined;
      hasEvent = false;
      return;
    }

    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') dataValues.push(value);
    else if (field === 'event') {
      eventValue = value;
      hasEvent = true;
    }
  }

  function processText(text, frames) {
    if (atStart && text.length !== 0) {
      atStart = false;
      if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
    }
    lineBuffer += text;
    let newline;
    while ((newline = lineBuffer.indexOf('\n')) !== -1) {
      let line = lineBuffer.slice(0, newline);
      lineBuffer = lineBuffer.slice(newline + 1);
      if (line.endsWith('\r')) line = line.slice(0, -1);
      processLine(line, frames);
    }
  }

  return {
    push(chunk) {
      if (poisoned) throw new Error('decoder is poisoned');
      if (finished) fail('decoder is finished');
      if (!(chunk instanceof Uint8Array)) fail('chunk must be a Uint8Array');
      const frames = [];
      try {
        processText(utf8.decode(chunk, {stream: true}), frames);
        return frames;
      } catch (error) {
        if (poisoned) throw error;
        return fail('invalid stream', error);
      }
    },

    finish() {
      if (poisoned) throw new Error('decoder is poisoned');
      if (finished) fail('decoder is finished');
      try {
        const frames = [];
        processText(utf8.decode(), frames);
        if (lineBuffer !== '') fail('unterminated final line');
        if (dataValues.length !== 0 || hasEvent) fail('pending frame fields');
        if (!terminated) fail('stream is not terminated');
        if (frames.length !== 0) fail('unexpected frame during finish');
        finished = true;
        return [];
      } catch (error) {
        if (poisoned) throw error;
        return fail('invalid stream', error);
      }
    },
  };
}

function decodeBase64(value) {
  if (typeof value !== 'string') throw new Error('every chunk must be a base64 string');
  const bytes = Buffer.from(value, 'base64');
  if (bytes.toString('base64') !== value) throw new Error('invalid canonical base64');
  return bytes;
}

function runCli(argv) {
  if (argv.length !== 1) throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const fileBytes = fs.readFileSync(argv[0]);
  let json = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true}).decode(fileBytes);
  if (json.charCodeAt(0) === 0xfeff) json = json.slice(1);
  const input = JSON.parse(json);
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error('input must be an object');
  }
  if (!Array.isArray(input.chunks)) throw new Error('chunks must be an array');

  const decoder = createDecoder();
  const frames = [];
  for (const encoded of input.chunks) frames.push(...decoder.push(decodeBase64(encoded)));
  frames.push(...decoder.finish());
  process.stdout.write(`${JSON.stringify({frames})}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    runCli(process.argv.slice(2));
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

