import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';

const script = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
const b64 = value => Buffer.from(value, 'utf8').toString('base64');

function fixture(t, contents, raw = false) {
  const directory = mkdtempSync(join(tmpdir(), 'stream-framer-'));
  t.after(() => rmSync(directory, {recursive: true, force: true}));
  const filename = join(directory, 'input.json');
  writeFileSync(filename, raw ? contents : JSON.stringify(contents));
  return filename;
}

function run(args) {
  return spawnSync(process.execPath, [script, ...args], {encoding: 'utf8'});
}

function assertCliError(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('CLI accepts a Unicode JSON file and prints one exact result', t => {
  const protocol = Buffer.from('event: 雪\r\ndata: hé😀\r\n\r\ndata: [DONE]\n\n');
  const chunks = [];
  for (const byte of protocol) chunks.push(Buffer.from([byte]).toString('base64'));
  chunks.splice(1, 0, '');
  const filename = fixture(t, {chunks, ignored: '✓'});
  const result = run([filename]);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, `${JSON.stringify({frames: [{event: '雪', data: 'hé😀'}]})}\n`);
});

test('CLI validates argument count, files, JSON, UTF-8, and object shape', t => {
  assertCliError(run([]));
  assertCliError(run(['one', 'two']));
  assertCliError(run([join(tmpdir(), `missing-stream-framer-${process.pid}`)]));

  const invalidInputs = [
    ['{', true],
    [Buffer.from([0xff]), true],
    [null, false],
    [[], false],
    ['text', false],
    [{}, false],
    [{chunks: null}, false],
    [{chunks: {}}, false],
  ];
  for (const [contents, raw] of invalidInputs) {
    assertCliError(run([fixture(t, contents, raw)]));
  }
});

test('CLI requires canonical standard padded base64 with canonical pad bits', t => {
  const invalid = [42, null, 'YQ', 'YQ=', 'YQ===', 'YR==', 'Y W E=', '_w==', '***=', '===='];
  for (const encoded of invalid) {
    const filename = fixture(t, {chunks: [encoded, b64('data: [DONE]\n\n')]});
    assertCliError(run([filename]));
  }
});

test('CLI suppresses already decoded frames when later protocol input fails', t => {
  const cases = [
    [b64('data: visible\n\n'), b64('bad trailing line')],
    [b64('data: visible\n\ndata: [DONE]\n\n'), b64(': forbidden\n')],
    [b64('data: visible\n\n')],
    [b64('data: [DONE]\n\n'), '/w=='],
  ];
  for (const chunks of cases) assertCliError(run([fixture(t, {chunks})]));
});

test('importing the module is inert', () => {
  const source = `import ${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)};`;
  const result = spawnSync(process.execPath, ['--input-type=module', '--eval', source], {encoding: 'utf8'});
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

