import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createDecoder} from '../stream-framer.js';

const script = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
const bytes = value => Buffer.from(value, 'utf8');

function fixture(t, chunks) {
  const directory = mkdtempSync(join(tmpdir(), 'stream-framer-hardening-'));
  t.after(() => rmSync(directory, {recursive: true, force: true}));
  const filename = join(directory, 'input.json');
  writeFileSync(filename, JSON.stringify({chunks}));
  return filename;
}

function run(filename) {
  return spawnSync(process.execPath, [script, filename], {
    encoding: 'utf8',
    maxBuffer: 32 * 1024 * 1024,
  });
}

test('CLI accumulates 150000 frames from one valid chunk without spread limits', t => {
  const count = 150000;
  const protocol = `${'data: x\n\n'.repeat(count)}data: [DONE]\n\n`;
  const result = run(fixture(t, [Buffer.from(protocol).toString('base64')]));
  const expectedFrames = Array.from({length: count}, () => ({event: 'message', data: 'x'}));

  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, `${JSON.stringify({frames: expectedFrames})}\n`);
  const output = JSON.parse(result.stdout);
  assert.equal(output.frames.length, count);
  assert.deepEqual(output.frames[0], {event: 'message', data: 'x'});
  assert.deepEqual(output.frames.at(-1), {event: 'message', data: 'x'});
});

test('CLI rejects noncanonical aliases of an otherwise valid padded stream', t => {
  const protocol = bytes('data: x\n\ndata: [DONE]\n\n');
  const canonical = protocol.toString('base64');
  assert.match(canonical, /=$/);

  const valid = run(fixture(t, [canonical]));
  assert.equal(valid.status, 0);
  assert.equal(valid.stderr, '');
  assert.equal(valid.stdout, `${JSON.stringify({frames: [{event: 'message', data: 'x'}]})}\n`);

  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const significant = canonical.length - 2;
  const canonicalIndex = alphabet.indexOf(canonical[significant]);
  assert.equal(canonicalIndex & 3, 0);
  const noncanonicalPadBits =
    canonical.slice(0, significant) + alphabet[canonicalIndex | 1] + canonical.slice(significant + 1);
  const aliases = [
    `${canonical.slice(0, 4)} \n${canonical.slice(4)}`,
    canonical.slice(0, -1),
    `${canonical}=`,
    noncanonicalPadBits,
  ];

  for (const alias of aliases) {
    assert.deepEqual(Buffer.from(alias, 'base64'), protocol);
    const result = run(fixture(t, [alias]));
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.notEqual(result.stderr, '');
  }
});

test('decoder preserves CR except the one directly before LF', () => {
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(bytes('data: left\rright\r\r\n\r\ndata: [DONE]\n\n')), [
    {event: 'message', data: 'left\rright\r'},
  ]);
  assert.deepEqual(decoder.finish(), []);
});

test('unknown field names are case-sensitive', () => {
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(bytes('Data: ignored\nEVENT: ignored\ndata: kept\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: 'kept'},
  ]);
  assert.deepEqual(decoder.finish(), []);
});

test('only the first of multiple leading BOMs is ignored', () => {
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(bytes('\ufeff\ufeffdata: ignored\n\ndata: kept\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: 'kept'},
  ]);
  assert.deepEqual(decoder.finish(), []);
});

test('frames returned earlier stay unchanged after a later push fails', () => {
  const decoder = createDecoder();
  const earlier = decoder.push(bytes('event: original\ndata: visible\n\n'));
  const snapshot = structuredClone(earlier);

  assert.throws(() => decoder.push(bytes('data: [DONE]\n\n: forbidden\n')), Error);
  assert.deepEqual(earlier, snapshot);
  assert.deepEqual(earlier, [{event: 'original', data: 'visible'}]);
  assert.throws(() => decoder.finish(), Error);
});

