function runCli(argv) {
  if (argv.length !== 1) throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const fileBytes = fs.readFileSync(argv[0]);
  let json = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true}).decode(fileBytes);
  if (json.charCodeAt(0) === 0xfeff) json = json.slice(1);
  const input = JSON.parse(json);
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error('input must be an object');
  }
  if (!Array.isArray(input.chunks)) throw new Error('chunks must be an array');

  const decoder = createDecoder();
  const frames = [];
  for (const encoded of input.chunks) {
    for (const frame of decoder.push(decodeBase64(encoded))) frames.push(frame);
  }
  for (const frame of decoder.finish()) frames.push(frame);
  process.stdout.write(`${JSON.stringify({frames})}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    runCli(process.argv.slice(2));
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}
