import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export function createDecoder() {
  const utf8 = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  let lineBuffer = '';
  let atStart = true;
  let dataValues = [];
  let eventValue;
  let hasEvent = false;
  let terminated = false;
  let finished = false;
  let poisoned = false;

  function fail(message, cause) {
    poisoned = true;
    throw new Error(message, cause === undefined ? undefined : {cause});
  }

  function processLine(line, frames) {
    if (terminated) {
      if (line !== '') fail('nonblank line after termination');
      return;
    }

    if (line === '') {
      if (dataValues.length !== 0) {
        const data = dataValues.join('\n');
        const event = !hasEvent || eventValue === '' ? 'message' : eventValue;
        if (data === '[DONE]') terminated = true;
        else frames.push({event, data});
      }
      dataValues = [];
      eventValue = undefined;
      hasEvent = false;
      return;
    }

    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') dataValues.push(value);
    else if (field === 'event') {
      eventValue = value;
      hasEvent = true;
    }
  }

  function processText(text, frames) {
    if (atStart && text.length !== 0) {
      atStart = false;
      if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
    }
    lineBuffer += text;
    let newline;
    while ((newline = lineBuffer.indexOf('\n')) !== -1) {
      let line = lineBuffer.slice(0, newline);
      lineBuffer = lineBuffer.slice(newline + 1);
      if (line.endsWith('\r')) line = line.slice(0, -1);
      processLine(line, frames);
    }
  }

  return {
    push(chunk) {
      if (poisoned) throw new Error('decoder is poisoned');
      if (finished) fail('decoder is finished');
      if (!(chunk instanceof Uint8Array)) fail('chunk must be a Uint8Array');
      const frames = [];
      try {
        processText(utf8.decode(chunk, {stream: true}), frames);
        return frames;
      } catch (error) {
        if (poisoned) throw error;
        return fail('invalid stream', error);
      }
    },

    finish() {
      if (poisoned) throw new Error('decoder is poisoned');
      if (finished) fail('decoder is finished');
      try {
        const frames = [];
