import test from 'node:test';
import assert from 'node:assert/strict';
import {createDecoder} from '../stream-framer.js';

const bytes = value => Buffer.from(value, 'utf8');
const expected = [
  {event: 'snow', data: '雪😀\nsecond'},
  {event: 'message', data: ''},
];
const wire = bytes('\ufeffevent: snow\r\ndata: 雪😀\r\ndata: second\r\n\r\ndata\n\ndata: [DONE]\r\n\r\n');

function decodeChunks(chunks) {
  const decoder = createDecoder();
  const frames = [];
  for (const chunk of chunks) frames.push(...decoder.push(chunk));
  assert.deepEqual(decoder.finish(), []);
  return frames;
}

function assertPoisoned(decoder) {
  assert.throws(() => decoder.push(bytes('data: [DONE]\n\n')), Error);
  assert.throws(() => decoder.finish(), Error);
}

function assertIndependentSuccess() {
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(bytes('data: ok\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: 'ok'},
  ]);
  assert.deepEqual(decoder.finish(), []);
}

test('output is invariant for whole input, every split, and bytewise input', () => {
  assert.deepEqual(decodeChunks([wire]), expected);
  for (let split = 0; split <= wire.length; split++) {
    assert.deepEqual(decodeChunks([wire.subarray(0, split), wire.subarray(split)]), expected);
  }
  assert.deepEqual(decodeChunks([...wire].map(byte => Uint8Array.of(byte))), expected);
});

test('frames reset fields and preserve exact values', () => {
  const decoder = createDecoder();
  const input = [
    'event: old', '',
    'data: default', '',
    'event: first', 'event: last', 'data:  one leading space', 'data:x:y', '',
    'event:', 'data:', '',
    ': comment', 'unknown: value', '',
    'data: [DONE]', '',
  ].join('\n') + '\n';
  assert.deepEqual(decoder.push(bytes(input)), [
    {event: 'message', data: 'default'},
    {event: 'last', data: ' one leading space\nx:y'},
    {event: 'message', data: ''},
  ]);
  assert.deepEqual(decoder.finish(), []);
});

test('DONE is exact, ignores its event, and permits only subsequent blank lines', () => {
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(bytes('data: [DONE] \n\nevent: x\ndata: [DONE]\n\n\n\r\n')), [
    {event: 'message', data: '[DONE] '},
  ]);
  assert.deepEqual(decoder.finish(), []);

  for (const suffix of ['data: [DONE]\n\n', ':comment\n', 'unknown\n', 'data: x\n']) {
    const bad = createDecoder();
    assert.throws(() => bad.push(bytes(`data: [DONE]\n\n${suffix}`)), Error);
    assertPoisoned(bad);
  }
});

test('strict UTF-8 rejects malformed and incomplete input and poisons', () => {
  const malformed = createDecoder();
  assert.throws(() => malformed.push(Uint8Array.of(0xff)), Error);
  assertPoisoned(malformed);

  const incomplete = createDecoder();
  assert.deepEqual(incomplete.push(Uint8Array.of(0xe2, 0x82)), []);
  assert.throws(() => incomplete.finish(), Error);
  assertPoisoned(incomplete);
  assertIndependentSuccess();
});

test('nonterminated lines, pending fields, and missing termination poison', () => {
  const cases = [
    decoder => { decoder.push(bytes('data: [DONE]\n\ntrailing')); decoder.finish(); },
    decoder => { decoder.push(bytes('data: pending\n')); decoder.finish(); },
    decoder => { decoder.push(bytes('event: pending\n')); decoder.finish(); },
    decoder => { decoder.push(bytes(': comment\nunknown: x\n')); decoder.finish(); },
  ];
  for (const trigger of cases) {
    const decoder = createDecoder();
    assert.throws(() => trigger(decoder), Error);
    assertPoisoned(decoder);
  }
  assertIndependentSuccess();
});

test('accepted chunks are not mutated and all other chunk types poison', () => {
  const backing = bytes('xx: typed comment\nyy');
  const offsetView = new Uint8Array(backing.buffer, backing.byteOffset + 2, backing.length - 4);
  for (const chunk of [Buffer.from(': buffer comment\n'), offsetView, Buffer.from(''), new Uint8Array()]) {
    // The task contract owns this assertion: it requires unchanged bytes, while Buffer identity remains valid.
    const before = Uint8Array.from(chunk);
    const decoder = createDecoder();
    assert.deepEqual(decoder.push(chunk), []);
    assert.deepEqual([...chunk], [...before]);
    decoder.push(bytes('data: [DONE]\n\n'));
    decoder.finish();
  }

  for (const value of ['', null, undefined, [], new ArrayBuffer(0), new DataView(new ArrayBuffer(0))]) {
    const decoder = createDecoder();
    assert.throws(() => decoder.push(value), Error);
    assertPoisoned(decoder);
  }
});

test('finish succeeds exactly once and no push is allowed afterward', () => {
  for (const action of ['finish', 'push']) {
    const decoder = createDecoder();
    decoder.push(bytes('data: [DONE]\n\n'));
    assert.deepEqual(decoder.finish(), []);
    if (action === 'finish') assert.throws(() => decoder.finish(), Error);
    else assert.throws(() => decoder.push(new Uint8Array()), Error);
    assertPoisoned(decoder);
  }
});

test('a later BOM is ordinary data while only one leading BOM is ignored', () => {
  const decoder = createDecoder();
  assert.deepEqual(decoder.push(bytes('\ufeffdata: \ufeffvalue\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '\ufeffvalue'},
  ]);
  assert.deepEqual(decoder.finish(), []);
});

